use dlm_core::{load_program_with_paths,lower_program,CheckPolicy,native};
use std::path::{Path,PathBuf};use std::process::Command;use std::sync::atomic::{AtomicUsize,Ordering};
#[path = "support/dln_runtime.rs"]
mod dln_runtime;
static SERIAL:AtomicUsize=AtomicUsize::new(0);
fn root()->PathBuf{Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")}
struct Work(PathBuf);impl Work{fn new()->Self{let p=std::env::temp_dir().join(format!("dlm-adaptive-{}-{}",std::process::id(),SERIAL.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&p).unwrap();Self(p)}}impl Drop for Work{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.0);}}
fn host(name:&str,library:Option<&Path>,w:&Path){let source=root().join("crates/dlm_core/tests/native_hosts").join(name);let out=w.join(if cfg!(windows){"host.exe"}else{"host"});let mut c=Command::new(dlm_core::default_c_compiler());c.args(["-std=gnu11","-O1","-Wall","-Wextra","-Werror","-Wno-misleading-indentation","-UNDEBUG"]).arg(source).arg(format!("-I{}",w.display()));if let Some(p)=library{c.arg(p);}if cfg!(windows){c.args(["-lshell32","-lws2_32","-lgdi32","-luser32"]);}else{c.args(["-pthread","-lm","-ldl"]);}let built=c.arg("-o").arg(&out).output().unwrap();assert!(built.status.success(),"{}",String::from_utf8_lossy(&built.stderr));let mut command=Command::new(out);dln_runtime::configure(&mut command);if name=="dln_adaptive_host.c"{command.arg(root().join("examples/native/fixtures"));}let ran=command.output().unwrap();assert!(ran.status.success(),"{}",String::from_utf8_lossy(&ran.stderr));assert!(String::from_utf8_lossy(&ran.stdout).contains(" OK"));}
#[test]fn native_authentication_migration_rotation_fragmentation_and_quota_faults(){let w=Work::new();host("dln_adaptive_host.c",None,&w.0);}
#[test]fn tun_packet_bridge_runs_real_packet_fd_io_without_claiming_driver_validation(){let w=Work::new();host("dln_tun_host.c",None,&w.0);}
#[test]fn actual_dlm_mutual_identity_gates_and_abi_match_the_native_adapter(){let w=Work::new();let p=load_program_with_paths(&root().join("crates/dlm_core/tests/native_hosts/dln_adaptive.dlm"),&[root().join("lib")]).unwrap();assert!(lower_program(&p,CheckPolicy::default()).is_err());let lowered=lower_program(&p,CheckPolicy::allow_unsafe()).unwrap();let library=w.0.join("dln_adaptive.a");native::build::build(&lowered.native,&library,&native::build::Options{artifact:native::build::Artifact::Staticlib,..Default::default()},false).unwrap();host("dln_adaptive_abi_host.c",Some(&library),&w.0);}
#[test]fn safe_source_cannot_mint_authority_clone_owners_or_forge_authenticated_paths(){let w=Work::new();let path=w.0.join("bad.dlm");for(body,expected)in[
("fn bad()->TunAuthority{return tun_authorize(true);}","unsafe"),
("fn bad(s:AdaptiveSession)->Unit{let duplicate:AdaptiveSession=s;}","explicit move"),
("fn bad(s:&AdaptiveSession)->Unit{let raw:&NetOpened=resource_get(&s.inner);let duplicate:AdaptiveSession=AdaptiveSession(resource(*raw));}","unsafe"),
("fn bad(s:&TunDevice)->Unit{let raw:&NetOpened=resource_get(&s.inner);let duplicate:TunDevice=TunDevice(resource(*raw));}","unsafe"),
("fn bad(s:&AdaptiveSession)->Unit{let e:NetworkError=adaptive_promote(s,AdaptivePath(1));}","mut"),
("fn bad(s:&mut AdaptiveSession,c:&Resource<OpaqueHandle,net_cancel_dispose>)->Unit guarantees(NoIO){let r:NetworkTransfer=adaptive_poll(s,0,c);}","NoIO"),
("fn bad(s:&mut TunBridge,c:&Resource<OpaqueHandle,net_cancel_dispose>)->Unit guarantees(NoBlocking){let r:NetworkTransfer=tun_bridge_poll(s,100,c);}","NoBlocking"),
("fn bad(t:TunDevice)->Unit{tun_close(move t);let e:NetworkError=tun_error(&t);}","use after move"),
("fn bad(s:&mut AdaptiveSession,p:ConnectionIdentity)->Unit{let e:NetworkError=adaptive_promote(s,p);}","AdaptivePath"),
]{std::fs::write(&path,format!("module test.adaptive.invalid\nimport std.net_tun\nnative{{ {body} }}\n")).unwrap();let p=load_program_with_paths(&path,&[root().join("lib")]).unwrap();let errors=match lower_program(&p,CheckPolicy::allow_unsafe()){Ok(_)=>panic!("unexpectedly accepted {body}"),Err(e)=>e};assert!(errors.iter().any(|e|e.message.to_lowercase().contains(&expected.to_lowercase())),"{body}: {errors:?}");}}
#[test]fn optimizer_is_pure_and_agrees_between_vm_and_c_without_loading_native_io(){let w=Work::new();let path=w.0.join("pure.dlm");std::fs::write(&path,"module test.optimizer.pure\nimport std.net_optimizer\nnative{fn main()->Unit{let p:OptimizerPolicy=optimizer_policy();let mut values:Array<RuntimeWitness,6>=zero<Array<RuntimeWitness,6>>();values[0]=RuntimeWitness(1,100,1000,1000000,4,0,3,151,1,true);values[1]=RuntimeWitness(2,100,2000,1000000,4,0,4,191,10,true);let c:OptimizerChoice=optimizer_select(TransportRequirements(8,0,0),p,values,100);assert(c.status==0 && c.id==2);let none:OptimizerChoice=optimizer_select(TransportRequirements(256,0,0),p,values,100);assert(none.status==6);}}\n").unwrap();let p=load_program_with_paths(&path,&[root().join("lib")]).unwrap();let n=lower_program(&p,CheckPolicy::default()).unwrap();assert!(!native::emit::emit(&n.native,true).contains("DLM_NATIVE_NET_PROVIDER"));native::vm::Vm::new(&n.native).run().unwrap();let exe=w.0.join(if cfg!(windows){"pure.exe"}else{"pure"});native::build::build(&n.native,&exe,&Default::default(),false).unwrap();assert!(Command::new(exe).status().unwrap().success());}
